    Bug 2061045 - Fix bct2 failures part 1 - Make calendar empty day and time slots accessible click targets. r=vineet

    Fix clicks on empty multiday hour boxes and month/multiweek day labels. This gives hour boxes gridcell semantics and labels with a single tab stop per column, and makes the selected month day heading an actionable button that creates an event from keyboard or mouse.

    TB-Tools-Id: eedf26d6-cde2-49d3-adb1-1fcff1e2dfcf

    Differential Revision: https://phabricator.services.mozilla.com/D316874

diff --git a/calendar/base/content/calendar-month-view.js b/calendar/base/content/calendar-month-view.js
index 275b24f089f..fb58bb61b72 100644
--- a/calendar/base/content/calendar-month-view.js
+++ b/calendar/base/content/calendar-month-view.js
@@ -53,6 +53,21 @@

       const monthDayLabels = document.createElement("h2");
       monthDayLabels.classList.add("calendar-month-day-box-dates");
+      monthDayLabels.setAttribute("role", "button");
+      monthDayLabels.tabIndex = -1;
+      monthDayLabels.addEventListener("click", event => this.onClick(event));
+      monthDayLabels.addEventListener("keydown", event => {
+        if (event.key != " " && event.key != "Enter") {
+          return;
+        }
+        event.preventDefault();
+        event.stopPropagation();
+        if (this.mDate) {
+          this.calendarView.selectedDay = this.mDate;
+        }
+        this.calendarView.controller.createNewEvent();
+      });
+      this.monthDayLabels = monthDayLabels;

       const weekLabel = document.createElement("span");
       weekLabel.setAttribute("data-label", "week");
@@ -99,9 +114,11 @@
     set selected(val) {
       if (val) {
         this.setAttribute("selected", "true");
+        this.monthDayLabels.tabIndex = 0;
         this.parentNode.setAttribute("selected", "true");
       } else {
         this.removeAttribute("selected");
+        this.monthDayLabels.tabIndex = -1;
         this.parentNode.removeAttribute("selected");
       }
     }
